/* agent lanes */
.ln-head{display:flex;align-items:center;gap:10px;padding:12px 16px;border-bottom:1px solid var(--line)}
.ln-head .t{font-weight:600;font-size:14px}
.ln-head .ghost{margin-left:auto}
.ln-row{display:grid;grid-template-columns:44px minmax(160px,1fr) minmax(140px,220px) 120px;align-items:center;gap:16px;padding:14px 16px;border-bottom:1px solid var(--line)}
.ln-row:last-child{border-bottom:0}
.ln-name{font-weight:600;font-size:14px}
.ln-task{font-size:13px;color:var(--text-dim)}
.ln-track{display:grid;grid-template-columns:repeat(3,1fr);gap:3px}
.ln-track i{height:4px;background:var(--line);position:relative;overflow:hidden}
.ln-track i b{position:absolute;left:0;top:0;bottom:0;width:0;background:var(--accent);transition:width .15s linear}
.ln-row.done .ln-track i b{background:var(--success)}
.ln-row .pill{justify-self:end}
.ln-row .nbox{width:36px;height:36px;box-shadow:0 0 0 5px var(--bg-deep)}
.ln-row.run .nbox{border-color:var(--accent-icon-line);color:var(--accent)}

/* ---------- agent lanes ---------- */
{
  const listEl = $('#ln-list'), title = $('#ln-title');
  const agents = [
    { name:'Researcher', ic:'search', tasks:['Reading competitor sites','Summarising pricing pages','Writing up findings'], sp:1.5 },
    { name:'Designer', ic:'dashboard', tasks:['Laying out pricing cards','Applying spacing tokens','Preparing variants'], sp:1.0 },
    { name:'Reviewer', ic:'check_circle', tasks:['Checking contrast','Reviewing copy','Signing off'], sp:1.8, wait:1 }
  ];
  agents.forEach(a => {
    const r = document.createElement('div'); r.className = 'ln-row';
    r.innerHTML = `<span class="nbox">${ic(a.ic,'sm')}</span><div><div class="ln-name">${a.name}</div><div class="ln-task fade-swap"></div></div><div class="ln-track"><i><b></b></i><i><b></b></i><i><b></b></i></div><span class="pill todo"><i></i><span>Queued</span></span>`;
    a.el = r; a.task = r.querySelector('.ln-task'); a.bars = $$('.ln-track b', r); a.pill = r.querySelector('.pill');
    listEl.appendChild(r);
  });
  let paused = false, finished = false, timer = null;
  function reset(){ finished = false; agents.forEach(a => { a.p = 0; a.ti = -1; a.state = ''; a.task.textContent = a.wait != null ? 'Waiting for the designer' : a.tasks[0]; }); swapText(title, '3 agents working'); }
  function paintA(a){
    a.bars.forEach((b, n) => b.style.width = Math.max(0, Math.min(100, (a.p - n * 33.34) / 33.34 * 100)) + '%');
    const ti = Math.min(2, Math.floor(a.p / 33.34));
    if (a.state === 'run' && ti !== a.ti){ a.ti = ti; swapText(a.task, a.tasks[ti]); if (ti > 0) ambient('c26', 'tick'); }
  }
  function setState(a, s){
    if (a.state === s) return; a.state = s; a.el.classList.toggle('run', s === 'run'); a.el.classList.toggle('done', s === 'done');
    if (s === 'run') setPill(a.pill, 'prog', 'Running');
    else if (s === 'wait') { setPill(a.pill, 'todo', 'Waiting'); swapText(a.task, 'Waiting for the designer'); }
    else if (s === 'done'){ setPill(a.pill, 'done', 'Done'); swapText(a.task, 'Finished'); ambient('c26', 'pop'); }
    else if (s === 'paused') setPill(a.pill, 'todo', 'Paused');
  }
  function tick(){
    if (paused || finished) return;
    agents.forEach(a => {
      if (a.state === 'done') return;
      if (a.wait != null && agents[a.wait].state !== 'done'){ setState(a, 'wait'); return; }
      setState(a, 'run'); a.p = Math.min(100, a.p + a.sp + Math.random() * .6); paintA(a);
      if (a.p >= 100) setState(a, 'done');
    });
    if (agents.every(a => a.state === 'done')){ finished = true; swapText(title, 'All agents finished'); ambient('c26', 'done'); setTimeout(() => { reset(); agents.forEach(paintA); }, 3000); }
  }
  $('#ln-pause').addEventListener('click', () => {
    paused = !paused; $('#ln-pause-t').textContent = paused ? 'Resume all' : 'Pause all'; $('#ln-pause-ic').textContent = paused ? 'play_arrow' : 'pause';
    agents.forEach(a => { if (a.state === 'done') return; if (paused){ a._prev = a.state; setState(a, 'paused'); } else { a.state = ''; } });
    swapText(title, paused ? 'Paused' : '3 agents working'); Sound.play(paused ? 'off' : 'on');
  });
  reset(); agents.forEach(paintA);
  whenSeen($('#c26'), () => { timer = setInterval(tick, 120); }, .3);
}
